"""PDC IaC Generator — PDC Workflow Step 3.

Generates Terraform, Ansible, and validation artifacts for CI/CD pipeline infrastructure.
Outputs JSON with artifact paths to stdout.
"""
import argparse
import json
import sys
import uuid
from datetime import datetime, timezone
from pathlib import Path

_ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(_ROOT))

_ARTIFACTS_DIR = _ROOT / "data" / "studio_artifacts" / "pdc"

# ── Terraform resource blocks ────────────────────────────────────────────────

_TF_HEADER = '''\
# CI/CD Pipeline Infrastructure — Generated by ICDEV™ PDC Workflow
# Canvas: pdc
# Generated: {ts}
# DO NOT EDIT — regenerate via PDC Workflow

terraform {{
  required_providers {{
    aws = {{
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }}
  }}
  required_version = ">= 1.6.0"
}}

provider "aws" {{
  region = var.aws_region
}}

locals {{
  common_tags = {{
    ManagedBy   = "icdev-pdc"
    Environment = var.environment
    Canvas      = "pdc"
  }}
}}

# ── S3 Artifact Bucket ────────────────────────────────────────────────────────

resource "aws_s3_bucket" "pipeline_artifacts" {{
  bucket = "${{var.pipeline_name}}-artifacts-${{data.aws_caller_identity.current.account_id}}"
  tags   = local.common_tags
}}

resource "aws_s3_bucket_versioning" "pipeline_artifacts_ver" {{
  bucket = aws_s3_bucket.pipeline_artifacts.id
  versioning_configuration {{ status = "Enabled" }}
}}

resource "aws_s3_bucket_public_access_block" "pipeline_artifacts_block" {{
  bucket                  = aws_s3_bucket.pipeline_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}}

# ── ECR Repository ────────────────────────────────────────────────────────────

resource "aws_ecr_repository" "app" {{
  name                 = var.ecr_repo_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {{
    scan_on_push = true
  }}

  encryption_configuration {{
    encryption_type = "KMS"
  }}

  tags = local.common_tags
}}

resource "aws_ecr_lifecycle_policy" "app" {{
  repository = aws_ecr_repository.app.name
  policy = jsonencode({{
    rules = [{{
      rulePriority = 1
      description  = "Expire untagged images after 30 days"
      selection = {{
        tagStatus   = "untagged"
        countType   = "sinceImagePushed"
        countUnit   = "days"
        countNumber = 30
      }}
      action = {{ type = "expire" }}
    }}]
  }})
}}

# ── IAM Role — CodePipeline ───────────────────────────────────────────────────

resource "aws_iam_role" "codepipeline" {{
  name = "${{var.pipeline_name}}-codepipeline-role"
  assume_role_policy = jsonencode({{
    Version = "2012-10-17"
    Statement = [{{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = {{ Service = "codepipeline.amazonaws.com" }}
    }}]
  }})
  tags = local.common_tags
}}

resource "aws_iam_role_policy" "codepipeline" {{
  name = "${{var.pipeline_name}}-codepipeline-policy"
  role = aws_iam_role.codepipeline.id
  policy = jsonencode({{
    Version = "2012-10-17"
    Statement = [
      {{
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:GetObjectVersion", "s3:PutObject"]
        Resource = "${{aws_s3_bucket.pipeline_artifacts.arn}}/*"
      }},
      {{
        Effect   = "Allow"
        Action   = ["codebuild:BatchGetBuilds", "codebuild:StartBuild"]
        Resource = "*"
      }},
    ]
  }})
}}

# ── IAM Role — CodeBuild ──────────────────────────────────────────────────────

resource "aws_iam_role" "codebuild" {{
  name = "${{var.pipeline_name}}-codebuild-role"
  assume_role_policy = jsonencode({{
    Version = "2012-10-17"
    Statement = [{{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = {{ Service = "codebuild.amazonaws.com" }}
    }}]
  }})
  tags = local.common_tags
}}

resource "aws_iam_role_policy" "codebuild" {{
  name = "${{var.pipeline_name}}-codebuild-policy"
  role = aws_iam_role.codebuild.id
  policy = jsonencode({{
    Version = "2012-10-17"
    Statement = [
      {{
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = "${{aws_s3_bucket.pipeline_artifacts.arn}}/*"
      }},
      {{
        Effect   = "Allow"
        Action   = ["ecr:GetAuthorizationToken", "ecr:BatchCheckLayerAvailability",
                    "ecr:PutImage", "ecr:InitiateLayerUpload", "ecr:UploadLayerPart",
                    "ecr:CompleteLayerUpload"]
        Resource = "*"
      }},
      {{
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "*"
      }},
    ]
  }})
}}

# ── CodeBuild — Build + Test ──────────────────────────────────────────────────

resource "aws_codebuild_project" "build" {{
  name          = "${{var.pipeline_name}}-build"
  description   = "Build and test stage"
  build_timeout = 20
  service_role  = aws_iam_role.codebuild.arn

  artifacts {{
    type = "CODEPIPELINE"
  }}

  environment {{
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = true

    environment_variable {{
      name  = "ECR_REPOSITORY_URI"
      value = aws_ecr_repository.app.repository_url
    }}
    environment_variable {{
      name  = "AWS_DEFAULT_REGION"
      value = var.aws_region
    }}
  }}

  source {{
    type      = "CODEPIPELINE"
    buildspec = "buildspec.yml"
  }}

  tags = local.common_tags
}}

# ── CodeBuild — Security Scan ─────────────────────────────────────────────────

resource "aws_codebuild_project" "security_scan" {{
  name          = "${{var.pipeline_name}}-security-scan"
  description   = "SAST, dependency scan, secrets detection"
  build_timeout = 15
  service_role  = aws_iam_role.codebuild.arn

  artifacts {{
    type = "CODEPIPELINE"
  }}

  environment {{
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }}

  source {{
    type      = "CODEPIPELINE"
    buildspec = "buildspec-security.yml"
  }}

  tags = local.common_tags
}}

# ── CodePipeline — 3-Stage Pipeline ──────────────────────────────────────────

resource "aws_codepipeline" "main" {{
  name     = var.pipeline_name
  role_arn = aws_iam_role.codepipeline.arn

  artifact_store {{
    location = aws_s3_bucket.pipeline_artifacts.bucket
    type     = "S3"
  }}

  stage {{
    name = "Source"
    action {{
      name             = "Source"
      category         = "Source"
      owner            = "AWS"
      provider         = "CodeCommit"
      version          = "1"
      output_artifacts = ["source_output"]
      configuration = {{
        RepositoryName = var.pipeline_name
        BranchName     = "main"
      }}
    }}
  }}

  stage {{
    name = "Build"
    action {{
      name             = "SecurityScan"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["source_output"]
      output_artifacts = ["scan_output"]
      configuration = {{
        ProjectName = aws_codebuild_project.security_scan.name
      }}
    }}
    action {{
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]
      configuration = {{
        ProjectName = aws_codebuild_project.build.name
      }}
      run_order = 2
    }}
  }}

  stage {{
    name = "Deploy"
    action {{
      name            = "ApproveDeployment"
      category        = "Approval"
      owner           = "AWS"
      provider        = "Manual"
      version         = "1"
      configuration = {{
        NotificationArn = aws_sns_topic.pipeline_notifications.arn
        CustomData      = "Review build artifacts before approving production deployment."
      }}
    }}
    action {{
      name            = "Deploy"
      category        = "Deploy"
      owner           = "AWS"
      provider        = "ECS"
      version         = "1"
      input_artifacts = ["build_output"]
      configuration = {{
        ClusterName = "${{var.pipeline_name}}-cluster"
        ServiceName = "${{var.pipeline_name}}-service"
        FileName    = "imagedefinitions.json"
      }}
      run_order = 2
    }}
  }}

  tags = local.common_tags
}}

# ── SNS Topic — Pipeline Notifications ───────────────────────────────────────

resource "aws_sns_topic" "pipeline_notifications" {{
  name = "${{var.pipeline_name}}-notifications"
  tags = local.common_tags
}}

# ── SSM Parameter Store ───────────────────────────────────────────────────────

resource "aws_ssm_parameter" "pdc_config" {{
  name  = "/icdev/pdc/config"
  type  = "String"
  value = jsonencode({{
    pipeline_name  = var.pipeline_name
    ecr_repo       = aws_ecr_repository.app.repository_url
    artifacts_bucket = aws_s3_bucket.pipeline_artifacts.bucket
    environment    = var.environment
  }})
  tags  = local.common_tags
}}

# ── Data Sources ──────────────────────────────────────────────────────────────

data "aws_caller_identity" "current" {{}}
data "aws_region" "current" {{}}
'''

