_VALIDATION_SCRIPT = '''\
#!/usr/bin/env python3
"""PDC Pipeline Infrastructure Validation — Generated by ICDEV™ PDC Workflow
Generated: {ts}

Run after terraform apply to verify all pipeline resources are active.
Usage:
  pip install boto3
  python validate_{uid}.py --region us-gov-west-1 [--profile <aws-profile>]
"""
import argparse
import sys
import boto3


def check(label, ok, detail=""):
    status = "PASS" if ok else "FAIL"
    msg = "  [" + status + "] " + str(label)
    if detail:
        msg += " -- " + str(detail)
    print(msg)
    return ok


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--region", default="us-gov-west-1")
    parser.add_argument("--profile", default=None)
    parser.add_argument("--pipeline-name", default="icdev-pdc-pipeline")
    parser.add_argument("--ecr-repo", default="icdev-app")
    args = parser.parse_args()

    session = boto3.Session(region_name=args.region, profile_name=args.profile)
    passed = 0
    failed = 0
    print("\\n=== PDC Pipeline Validation ===\\n")

    # Check CodePipeline status
    try:
        cp = session.client("codepipeline")
        pipeline = cp.get_pipeline(name=args.pipeline_name)
        ok = check("CodePipeline (" + args.pipeline_name + ")", bool(pipeline.get("pipeline")))
        passed += ok
        failed += not ok
    except Exception as e:
        ok = check("CodePipeline (" + args.pipeline_name + ")", False, str(e))
        passed += ok
        failed += not ok

    # Check CodeBuild projects
    try:
        cb = session.client("codebuild")
        projects = cb.list_projects()["projects"]
        build_found = any(args.pipeline_name in p for p in projects)
        ok = check("CodeBuild projects", build_found, str(len(projects)) + " total projects")
        passed += ok
        failed += not ok
    except Exception as e:
        ok = check("CodeBuild projects", False, str(e))
        passed += ok
        failed += not ok

    # Check ECR repository
    try:
        ecr = session.client("ecr")
        repos = ecr.describe_repositories(repositoryNames=[args.ecr_repo])["repositories"]
        ok = check("ECR repository (" + args.ecr_repo + ")", bool(repos))
        passed += ok
        failed += not ok
    except Exception as e:
        ok = check("ECR repository (" + args.ecr_repo + ")", False, str(e))
        passed += ok
        failed += not ok

    # Check S3 artifact bucket
    try:
        s3 = session.client("s3")
        import boto3
        sts = session.client("sts")
        account_id = sts.get_caller_identity()["Account"]
        bucket = args.pipeline_name + "-artifacts-" + account_id
        s3.head_bucket(Bucket=bucket)
        ok = check("S3 artifact bucket (" + bucket + ")", True)
        passed += ok
        failed += not ok
    except Exception as e:
        ok = check("S3 artifact bucket", False, str(e))
        passed += ok
        failed += not ok

    print("\\n=== Result: " + str(passed) + " passed, " + str(failed) + " failed ===\\n")
    sys.exit(0 if failed == 0 else 1)


if __name__ == "__main__":
    main()
'''

_IAC_REPORT = '''\
# PDC IaC Generation Report
**Generated:** {ts}
**Project:** {project_id}
**Canvas:** pdc

## Generated Artifacts

| Artifact | Path | Description |
|----------|------|-------------|
| Terraform Main | `{main_tf}` | AWS CodePipeline + CodeBuild + ECR + S3 |
| Terraform Variables | `{vars_tf}` | Variable declarations |
| Terraform tfvars | `{tfvars}` | Example variable values |
| Ansible Playbook | `{ansible_pb}` | Build agent configuration |
| Validation Script | `{validate_py}` | Post-deploy boto3 checks |
| This Report | `{report_path}` | IaC generation summary |

## Resources Provisioned

- `aws_codepipeline` — 3-stage pipeline: Source → Build → Deploy
- `aws_codebuild_project` (build) — Build + test stage
- `aws_codebuild_project` (security_scan) — SAST, dependency scan, secrets detection
- `aws_ecr_repository` — Container image registry (immutable tags, scan on push)
- `aws_s3_bucket` + versioning — Pipeline artifact storage
- `aws_iam_role` (codepipeline) — CodePipeline execution role
- `aws_iam_role` (codebuild) — CodeBuild execution role
- `aws_sns_topic` — Pipeline approval notifications
- `aws_ssm_parameter` — Encrypted pipeline configuration

## Apply Instructions

```bash
cp terraform.tfvars.example terraform.tfvars
# Edit terraform.tfvars — fill in vpc_id, subnet_ids, pipeline_name
terraform init
terraform plan -var-file=terraform.tfvars
terraform apply -var-file=terraform.tfvars
python validate_{uid}.py --region us-gov-west-1 --pipeline-name icdev-pdc-pipeline
```

## Approval Required

**Approver Role:** `devops_lead`
Obtain DevOps Lead sign-off before applying to production environments.
'''


def generate_iac(project_id: str) -> dict:
    _ARTIFACTS_DIR.mkdir(parents=True, exist_ok=True)
    tf_dir = _ARTIFACTS_DIR / "terraform"
    tf_dir.mkdir(parents=True, exist_ok=True)

    ts = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    uid = uuid.uuid4().hex[:8]

    main_tf = tf_dir / f"main_{uid}.tf"
    vars_tf = tf_dir / "variables.tf"
    tfvars = tf_dir / "terraform.tfvars.example"
    ansible_pb = _ARTIFACTS_DIR / f"ansible_playbook_{uid}.yml"
    validate_py = _ARTIFACTS_DIR / f"validate_{uid}.py"
    report_path = _ARTIFACTS_DIR / f"iac_report_{uid}.md"

    main_tf.write_text(_TF_HEADER.format(ts=ts), encoding="utf-8")
    vars_tf.write_text(_TF_VARIABLES, encoding="utf-8")
    tfvars.write_text(_TFVARS_EXAMPLE, encoding="utf-8")
    ansible_pb.write_text(_ANSIBLE_PLAYBOOK.format(ts=ts), encoding="utf-8")
    validate_py.write_text(_VALIDATION_SCRIPT.format(ts=ts, uid=uid), encoding="utf-8")

    report_md = _IAC_REPORT.format(
        ts=datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"),
        project_id=project_id,
        main_tf=main_tf.relative_to(_ROOT).as_posix(),
        vars_tf=vars_tf.relative_to(_ROOT).as_posix(),
        tfvars=tfvars.relative_to(_ROOT).as_posix(),
        ansible_pb=ansible_pb.relative_to(_ROOT).as_posix(),
        validate_py=validate_py.relative_to(_ROOT).as_posix(),
        report_path=report_path.relative_to(_ROOT).as_posix(),
        uid=uid,
    )
    report_path.write_text(report_md, encoding="utf-8")

    return {
        "uid": uid,
        "main_tf": main_tf.relative_to(_ROOT).as_posix(),
        "vars_tf": vars_tf.relative_to(_ROOT).as_posix(),
        "tfvars": tfvars.relative_to(_ROOT).as_posix(),
        "ansible_pb": ansible_pb.relative_to(_ROOT).as_posix(),
        "validate_py": validate_py.relative_to(_ROOT).as_posix(),
        "report_path": report_path.relative_to(_ROOT).as_posix(),
    }


def main():
    parser = argparse.ArgumentParser(description="PDC IaC Generator")
    parser.add_argument("--project-id", default="default")
    parser.add_argument("--run-id", default="")
    parser.add_argument("--canvas", default="pdc")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args()

    try:
        result = generate_iac(args.project_id)

        output = {
            "gate": "PASS",
            "canvas": "pdc",
            "artifacts": [
                {"name": "Terraform Main", "path": result["main_tf"], "type": "tf"},
                {"name": "Terraform Variables", "path": result["vars_tf"], "type": "tf"},
                {"name": "Terraform tfvars", "path": result["tfvars"], "type": "tf"},
                {"name": "Ansible Build Agent Playbook", "path": result["ansible_pb"], "type": "yml"},
                {"name": "Validation Script", "path": result["validate_py"], "type": "py"},
                {"name": "IaC Generation Report", "path": result["report_path"], "type": "md"},
            ],
        }
        print(json.dumps(output))
        sys.exit(0)
    except Exception as exc:
        print(json.dumps({"gate": "FAIL", "canvas": "pdc", "error": str(exc), "artifacts": []}))
        sys.exit(1)


if __name__ == "__main__":
    main()
